#!/bin/bash
set -Eeuo pipefail
umask 077
python3 <<'PYREMOTE'
from pathlib import Path
import os,stat,json,base64,gzip,subprocess,tempfile,shutil,hashlib
files=json.loads(gzip.decompress(base64.b64decode('')))
base=Path('/srv/celikom/app/staging-20261122/src/Application')
targets={name:base/name for name in ['Mp3Metadata.php','Mp3Normalizer.php']}
old={}
for name,p in targets.items():
 if p.exists():
  st=p.lstat();assert stat.S_ISREG(st.st_mode) and not p.is_symlink()
  old[name]=(p.read_bytes(),st.st_uid,st.st_gid,stat.S_IMODE(st.st_mode))
assert hashlib.sha256(old['Mp3Normalizer.php'][0]).hexdigest()=='54115c544d0d3fbf5f524b4b60b7c9648ac33edf752f5b55e2f9fd2943e987ea','LIVE_NORMALIZER_CHANGED_REFUSED'
assert 'Mp3Metadata.php' not in old,'UNEXPECTED_METADATA_HELPER_REFUSED'
d=Path(tempfile.mkdtemp(prefix='celikom-metadata97-deploy-',dir='/tmp'))
backup=Path(tempfile.mkdtemp(prefix='backend-backup-097-',dir='/srv/celikom-releases/private/extension'))
for name,values in old.items():
 p=backup/name;p.write_bytes(values[0]);p.chmod(0o600)
replaced=[]
def atomic(p,data,uid,gid,mode):
 fd,name=tempfile.mkstemp(prefix='.metadata97-',dir=p.parent)
 try:
  with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
  os.chown(name,uid,gid);os.chmod(name,mode);os.replace(name,p)
 finally:
  if os.path.exists(name):os.unlink(name)
try:
 os.chown(d,0,33);d.chmod(0o750)
 for name in targets:
  p=d/name;p.write_text(files['server/src/Application/'+name]);os.chown(p,0,33);p.chmod(0o640)
  r=subprocess.run(['runuser','-u','www-data','--','php','-l',str(p)],capture_output=True,text=True,timeout=10)
  assert r.returncode==0,'CANDIDATE_LINT_FAILED'
 probe=d/'probe.php';probe.write_text(files['probe.php']);os.chown(probe,0,33);probe.chmod(0o640)
 r=subprocess.run(['runuser','-u','www-data','--','php','-l',str(probe)],capture_output=True,text=True,timeout=10)
 assert r.returncode==0,'HTTP_PROBE_LINT_FAILED'
 tone=d/'tone.mp3';tone.write_bytes(gzip.decompress(base64.b64decode(files['tone'])));os.chown(tone,0,33);tone.chmod(0o640)
 for name,p in targets.items():
  previous=old.get(name,old['Mp3Normalizer.php'])
  atomic(p,(d/name).read_bytes(),*previous[1:]);replaced.append(name)
 print('MP3_METADATA_097_DEPLOYED_EXACT_HASHES',json.dumps({name:hashlib.sha256(p.read_bytes()).hexdigest() for name,p in targets.items()}),flush=True)
 r=subprocess.run(['runuser','-u','www-data','--','php',str(probe),str(tone)],capture_output=True,text=True,timeout=180)
 print(r.stdout[-9000:],end='',flush=True)
 if r.returncode:print('HTTP_PROBE_STDERR',r.stderr[-1500:]);raise RuntimeError('HTTP_TAGGED_UPLOAD_FAILED')
 print('MP3_METADATA_097_REAL_HTTPS_UPLOAD_VALIDATION_SUCCESS',flush=True)
except BaseException:
 for name in reversed(replaced):
  if name in old:atomic(targets[name],*old[name])
  else:targets[name].unlink()
 print('MP3_METADATA_097_ROLLED_BACK',flush=True)
 raise
finally:shutil.rmtree(d)
PYREMOTE

python3 <<'PYBUILD'
